   924  static ALWAYS_INLINE int max(int a, int b)
   925  {
   926      return (a > b) ? a : b;
   927  }
   928
   929  static ALWAYS_INLINE int calculate_n_packets(size_t total)
   930  {
   931      /* 740 = 1480 (a common MTU) / 2, so that Lwan'll optimistically error out
   932       * after ~2x number of expected packets to fully read the request body.*/
   933      return max(1, (int)(total / 740));
   934  }
